/* aesthetic meter v2.16.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-warn: #8a5f32;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-warn-dark: #c49d72;
  --ae-gentle: 480ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
    --ae-warn: var(--ae-warn-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
  --ae-warn: var(--ae-warn-dark);
}

.ae-warn {
color: var(--ae-warn);
}

.ae-meter {
position: relative;
  height: 4px;
  background: var(--ae-wash);
  border: 1px solid var(--ae-line);
}

.ae-meter-fill {
position: absolute;
  inset: 0 auto 0 0;
  background: var(--ae-ink);
  transition: width var(--ae-gentle) var(--ae-ease);
}

.ae-meter-fill.ae-warn {
background: var(--ae-warn);
}

.ae-meter-mark {
position: absolute;
  top: -3px;
  bottom: -3px;
  width: 1px;
  background: var(--ae-ink-muted);
}
